import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788283422000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><p>Every one is optional. The server starts with none of them set, lists its tools, and fails each call with setup instructions — which is what lets registries and sandbox inspectors introspect it.</p><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to “Credentials”">​</a></h2><p>Tried in this order; the first one that is present wins.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>GSC_SERVICE_ACCOUNT_KEY</code></td><td>Service account key, as raw JSON or base64-encoded JSON</td></tr><tr><td><code>GSC_SERVICE_ACCOUNT_KEY_FILE</code></td><td>Path to a service account key file. Setting this <strong>and</strong> the above is a startup error</td></tr><tr><td><code>GSC_CLIENT_ID</code></td><td>OAuth2 client id</td></tr><tr><td><code>GSC_CLIENT_SECRET</code></td><td>OAuth2 client secret</td></tr><tr><td><code>GSC_REFRESH_TOKEN</code></td><td>OAuth2 refresh token</td></tr><tr><td><code>GOOGLE_APPLICATION_CREDENTIALS</code></td><td>Path to application default credentials</td></tr><tr><td><code>GOOGLE_CLOUD_PROJECT</code></td><td>Also makes the server consider application default credentials</td></tr></tbody></table><p>The three OAuth2 variables are required <strong>together</strong>. A partial triple is a startup error rather than a fall-through to application default credentials — see <a href="/guide/configuration#the-credential">Configuration</a> for why.</p><p>Application default credentials are only attempted when one of the two <code>GOOGLE_</code> variables points at something. Otherwise <code>google-auth-library</code> would search the gcloud config directory and then the metadata server on every call, and a 30-second metadata timeout is a far worse answer than &quot;you configured nothing&quot;.</p><p><code>GSC_SERVICE_ACCOUNT_KEY</code>, <code>GSC_CLIENT_SECRET</code> and <code>GSC_REFRESH_TOKEN</code> are deleted from the environment once read.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>GSC_SITE_URL</code></td><td>Default property. Makes <code>site_url</code> optional on every tool that takes one — except <code>add_site</code></td></tr><tr><td><code>GSC_ALLOWED_SITES</code></td><td>Comma-separated properties this server may touch at all. Anything else is refused before a request goes out</td></tr></tbody></table><p>Both are normalised on read: a URL-prefix property gains its required trailing slash, a domain property is lower-cased, and a bare hostname is rejected. A <code>GSC_SITE_URL</code> that <code>GSC_ALLOWED_SITES</code> would then refuse is a startup error — valid on both lines and broken as a pair.</p><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to “Tools”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>GSC_READ_ONLY</code></td><td><code>true</code> registers only the twelve read tools, and requests <code>webmasters.readonly</code></td></tr><tr><td><code>GSC_ALLOW_TOOLS</code></td><td>Comma-separated tool names, a prefix with one trailing <code>*</code>, or <code>essential</code></td></tr><tr><td><code>GSC_DENY_TOOLS</code></td><td>Same shape, subtracted from whatever the allow list left</td></tr></tbody></table><p>An empty or whitespace-only value counts as <strong>unset</strong>, so <code>GSC_ALLOW_TOOLS=</code> in a compose file does not mean &quot;allow nothing&quot;. An entry that matches no tool stops the server with the list of real names.</p><p>See <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><h2 id="asking-a-person" tabindex="-1">Asking a person <a class="header-anchor" href="#asking-a-person" aria-label="Permalink to “Asking a person”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>ELICITATION</code></td><td><code>false</code> replaces the approval dialog with the two-call token. Default <code>true</code>. <strong>Not prefixed</strong></td></tr></tbody></table><p>Whether a client that <em>can</em> show a dialog is asked before <code>delete_site</code>, <code>delete_sitemap</code>, <code>unverify_site</code> or <code>update_site_owners</code> acts. <code>false</code> takes the two-call-token path instead — it does not remove the guard, and a server started with it off prints one line saying so.</p><p>Two ways it differs from every other variable on this page:</p><ul><li><strong>No prefix.</strong> One <code>export ELICITATION=false</code> reaches every MCP server in the same environment, not just this one. That is the point of it and also its risk; see <a href="/guide/approval">Asking a person</a>.</li><li><strong>Fatal on anything else.</strong> Where <code>GSC_READ_ONLY</code> fails <em>off</em> on a typo, this one stops the server with exit code 1. It is the only variable here that defaults to <em>on</em>, and a typo that fell back would leave the dialog running while you believed it was off.</li></ul><p>Values are trimmed and matched case-insensitively. It is read <em>after</em> the credentials are deleted from <code>process.env</code>, so the fatal path cannot leave them sitting there for a crash reporter.</p>`,21)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};